import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/quickstart.md","filePath":"zh/quickstart.md","lastUpdated":null}'),o={name:"zh/quickstart.md"};function n(l,e,i,h,p,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>安装完成后，第一次启动应用即可使用。</p><h2 id="第-1-步-启动" tabindex="-1">第 1 步：启动 <a class="header-anchor" href="#第-1-步-启动" aria-label="Permalink to &quot;第 1 步：启动&quot;">​</a></h2><p>双击桌面图标或开始菜单快捷方式启动。应用会自动拉起并嵌入 DeepSeek Harness Web UI。</p><ul><li>首次启动若<strong>未检测到内核</strong>，会显示全屏安装引导。</li><li>选择镜像源（官方 registry.npmjs.org 或 npmmirror 镜像）、是否包含测试版与要安装的版本，点击<strong>安装内核</strong>。</li><li>安装完成后应用自动启动 dsh，出现 Web UI 即代表就绪。</li></ul><h2 id="第-2-步-标签页" tabindex="-1">第 2 步：标签页 <a class="header-anchor" href="#第-2-步-标签页" aria-label="Permalink to &quot;第 2 步：标签页&quot;">​</a></h2><p>窗口顶部是无边框自绘标题栏，左侧即<strong>浏览器式标签条</strong>：</p><ol><li><strong>DeepSeek UI</strong> —— 内嵌的 DeepSeek Harness 主界面（默认）。</li><li><strong>网页版对话</strong> —— 内嵌 <a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">chat.deepseek.com</a>，用于网页对话。</li><li><strong>用量 / 充值</strong> —— 内嵌 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>，查看用量与充值余额。</li></ol><p>这三个是<strong>固定标签</strong>，始终存在、不可关闭。此外：</p><ul><li>页面里点开的新链接（<code>target=_blank</code>）会自动变成一个<strong>动态标签</strong>；</li><li>点标签条上的「<strong>＋</strong>」可主动新建——默认打开<strong>内置导航页</strong>（带搜索框与常用站点），也可在设置里改为打开<strong>自定义网址</strong>；</li><li>标签可以拖动排序；拖到另一个窗口顶部的浅蓝遮罩，还能把标签<strong>移入那个窗口</strong>；</li><li>右侧依次是设置、最小化 / 最大化 / 关闭按钮（终端已收进设置页，见<a href="/zh/settings">设置说明</a>）。</li></ul><div class="tip custom-block"><p class="custom-block-title">快捷操作</p><p>按住 <strong>Ctrl</strong>（macOS 为 <strong>Cmd</strong>）点击任意标签，会用系统默认浏览器打开该标签的网址；普通点击则在应用内切换。</p></div><p>完整说明见<a href="/zh/usage">标签页与多窗口</a>。</p><h2 id="第-3-步-可选设置" tabindex="-1">第 3 步：可选设置 <a class="header-anchor" href="#第-3-步-可选设置" aria-label="Permalink to &quot;第 3 步：可选设置&quot;">​</a></h2><p>进入 <strong>设置</strong> 可调整工作目录、端口、外观、内核更新与开发模式等，详见<a href="/zh/settings">设置说明</a>。</p><h2 id="现在可以开始了" tabindex="-1">现在可以开始了 <a class="header-anchor" href="#现在可以开始了" aria-label="Permalink to &quot;现在可以开始了&quot;">​</a></h2><p>在 DeepSeek Harness Web UI 内进行对话、使用工作区文件系统等功能。有疑问先看<a href="/zh/faq">常见问题</a>。</p>',16)])])}const m=t(o,[["render",n]]);export{d as __pageData,m as default};
